fn main() {
    // Generated by scripts/prepare-resources.sh (pnpm dev and pnpm build run
    // it); the binary embeds them.
    let resource = "resources/turbo-args.json";
    println!("cargo:rerun-if-changed={resource}");
    if !std::path::Path::new(resource).exists() {
        panic!("{resource} is missing: run `sh scripts/prepare-resources.sh` in eink-qemu/desktop first.");
    }
    tauri_build::build()
}
